دالة سطّح_القائمة(ق) {
    متغير مسطّح = []
    من_أجل (ع في ق) {
        إذا (نوع(ع) == "قائمة") {
            مسطّح = أضف(مسطّح, سطّح_القائمة(ع))
        } وإلا {
            مسطّح = أضف(مسطّح, ع)
        }
    }
    ارجع مسطّح
}

# مثال للاستخدام (بدون تعريف قائمة_متداخلة لأنك طلبت فقط تصحيح الشيفرة)
# لكن، لإظهار كيفية استخدام الدالة، سأضيف مثالًا هنا:

# تعريف قائمة متداخلة
متغير قائمة_متداخلة = [١, [٢, [٣, ٤]], ٥]

# استدعاء الدالة سطّح_القائمة
متغير مسطّحة = سطّح_القائمة(قائمة_متداخلة)

# طباعة النتيجة (تمت إضافتها فقط للتوضيح، ولكنها ليست جزءًا من الدالة نفسها)
اطبع(مسطّحة) # يجب أن تطبع: ١-٢-٣-٤-٥

# اختبار مع قائمة فارغة
متغير قائمة_فارغة = []
متغير مسطّحة_فارغة = سطّح_القائمة(قائمة_فارغة)
اطبع(مسطّحة_فارغة) # يجب أن تطبع: ٠

