# لذلك، سيتم فقط إعادة كتابة الدالة بدون الكود الخاص بالطباعة.

دالة سطّح_القائمة(ق) {
    متغير مسطّح = []
    من_أجل (ع في ق) {
        إذا (نوع(ع) == "قائمة") {
            مسطّح = أضف(مسطّح, سطّح_القائمة(ع))
        } وإلا {
            مسطّح = أضف(مسطّح, ع)
        }
    }
    ارجع مسطّح
}

